#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
from datetime import datetime, timezone
ROOT = Path(__file__).resolve().parent

def utc_now(): return datetime.now(timezone.utc).isoformat(timespec="seconds")
def write(path, content):
    target = ROOT / path; target.parent.mkdir(parents=True, exist_ok=True); target.write_text(content, encoding="utf-8"); print(f"[WRITE] {path}")
def create_json(path, data):
    target = ROOT / path; target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists(): print(f"[SKIP] {path}"); return
    target.write_text(json.dumps(data, indent=2), encoding="utf-8"); print(f"[CREATE] {path}")
def main():
    print("=== Applying Buster v4.5 Presence + Visual Learning Patch ===")
    write('buster/presence/__init__.py', 'from .modes import PresenceMode, EmotionalState, PresencePriority\nfrom .director import ConversationDirector\nfrom .ambient_awareness import AmbientAwareness\nfrom .context_awareness import ContextAwareness\nfrom .engine import PresenceEngine\n\n__all__ = ["PresenceMode", "EmotionalState", "PresencePriority", "ConversationDirector", "AmbientAwareness", "ContextAwareness", "PresenceEngine"]\n')
    write('buster/presence/modes.py', 'from __future__ import annotations\n\nclass PresenceMode:\n    SILENT = "silent"\n    ASSISTANT = "assistant"\n    COMPANION = "companion"\n    ENGINEER = "engineer"\n\nclass EmotionalState:\n    RELAXED = "relaxed"\n    THINKING = "thinking"\n    WORKING = "working"\n    INVESTIGATING = "investigating"\n    LEARNING = "learning"\n    CONCERNED = "concerned"\n    SATISFIED = "satisfied"\n\nclass PresencePriority:\n    LOW = "low"\n    NORMAL = "normal"\n    IMPORTANT = "important"\n    URGENT = "urgent"\n\nPRIORITY_SCORE = {PresencePriority.LOW: 1, PresencePriority.NORMAL: 2, PresencePriority.IMPORTANT: 3, PresencePriority.URGENT: 4}\n\ndef state_for_activity(activity: str) -> str:\n    text = (activity or "").lower()\n    if any(word in text for word in ["error", "failed", "failure", "crash"]): return EmotionalState.CONCERNED\n    if any(word in text for word in ["fix", "investigate", "debug"]): return EmotionalState.INVESTIGATING\n    if any(word in text for word in ["build", "run", "generate", "working"]): return EmotionalState.WORKING\n    if any(word in text for word in ["plan", "think", "strategy", "decide"]): return EmotionalState.THINKING\n    if any(word in text for word in ["learn", "pattern", "experience"]): return EmotionalState.LEARNING\n    if any(word in text for word in ["complete", "success", "approved", "passed"]): return EmotionalState.SATISFIED\n    return EmotionalState.RELAXED\n')
    write('buster/presence/director.py', 'from __future__ import annotations\nimport json\nfrom pathlib import Path\nfrom datetime import datetime, timezone\nfrom typing import Dict, Any, List\nfrom .modes import PresenceMode, PresencePriority, PRIORITY_SCORE\n\nDEFAULT_SETTINGS = {\n    "enabled": True, "mode": PresenceMode.COMPANION, "quiet_mode": False,\n    "cooldown_seconds": 20, "max_items_per_hour": 24, "min_priority": PresencePriority.NORMAL,\n    "allow_greetings": True, "allow_idle_checkins": True,\n    "allow_camera_learning_comments": True, "allow_engineering_suggestions": True,\n}\n\nclass ConversationDirector:\n    """Single gatekeeper that decides if Buster should talk first."""\n    def __init__(self, data_dir: str | Path = "data") -> None:\n        self.data_dir = Path(data_dir); self.data_dir.mkdir(parents=True, exist_ok=True)\n        self.settings_path = self.data_dir / "presence_settings.json"\n        self.queue_path = self.data_dir / "presence_speech_queue.json"\n        self.state_path = self.data_dir / "presence_state.json"\n        self.settings = self._load_json(self.settings_path, DEFAULT_SETTINGS)\n        self._ensure_files()\n    def _now(self) -> str: return datetime.now(timezone.utc).isoformat(timespec="seconds")\n    def _load_json(self, path: Path, default: Any) -> Any:\n        if not path.exists():\n            path.write_text(json.dumps(default, indent=2), encoding="utf-8")\n            return default.copy() if isinstance(default, dict) else default\n        try: return json.loads(path.read_text(encoding="utf-8"))\n        except Exception: return default.copy() if isinstance(default, dict) else default\n    def _save_json(self, path: Path, data: Any) -> None: path.write_text(json.dumps(data, indent=2), encoding="utf-8")\n    def _ensure_files(self) -> None:\n        self._load_json(self.queue_path, [])\n        self._load_json(self.state_path, {"mode": self.settings.get("mode", PresenceMode.COMPANION), "last_spoken": None, "last_emotion": "relaxed", "updated": self._now()})\n    def set_mode(self, mode: str) -> Dict[str, Any]:\n        if mode not in [PresenceMode.SILENT, PresenceMode.ASSISTANT, PresenceMode.COMPANION, PresenceMode.ENGINEER]: raise ValueError(f"Unknown presence mode: {mode}")\n        self.settings["mode"] = mode; self._save_json(self.settings_path, self.settings)\n        state = self._load_json(self.state_path, {}); state.update({"mode": mode, "updated": self._now()}); self._save_json(self.state_path, state); return state\n    def should_speak(self, priority: str = PresencePriority.NORMAL, category: str = "general") -> bool:\n        if not self.settings.get("enabled", True): return False\n        if self.settings.get("quiet_mode", False): return priority == PresencePriority.URGENT\n        mode = self.settings.get("mode", PresenceMode.COMPANION)\n        if mode == PresenceMode.SILENT: return priority == PresencePriority.URGENT\n        if mode == PresenceMode.ASSISTANT and priority == PresencePriority.LOW: return False\n        if mode == PresenceMode.ENGINEER and category not in ["engineering", "mission", "error", "learning", "system"]: return priority in [PresencePriority.IMPORTANT, PresencePriority.URGENT]\n        min_priority = self.settings.get("min_priority", PresencePriority.NORMAL)\n        return PRIORITY_SCORE.get(priority, 2) >= PRIORITY_SCORE.get(min_priority, 2)\n    def request_speech(self, message: str, priority: str = PresencePriority.NORMAL, category: str = "general", reason: str = "") -> Dict[str, Any]:\n        item = {"timestamp": self._now(), "message": message, "priority": priority, "category": category, "reason": reason, "approved": self.should_speak(priority, category)}\n        queue: List[Dict[str, Any]] = self._load_json(self.queue_path, []); queue.append(item); self._save_json(self.queue_path, queue[-250:]); return item\n    def greeting(self, name: str = "Adam") -> Dict[str, Any]: return self.request_speech(f"Good morning {name}. I\'m online and ready.", PresencePriority.NORMAL, "presence", "daily greeting")\n    def engineering_update(self, message: str, reason: str = "engineering update") -> Dict[str, Any]: return self.request_speech(message, PresencePriority.IMPORTANT, "engineering", reason)\n')
    write('buster/presence/ambient_awareness.py', 'from __future__ import annotations\nfrom typing import Dict, Any, Optional\nfrom .modes import PresencePriority\nfrom .director import ConversationDirector\n\nclass AmbientAwareness:\n    IMPORTANT_EVENTS = {\n        "build_completed": (PresencePriority.IMPORTANT, "Build completed successfully."),\n        "tests_failed": (PresencePriority.IMPORTANT, "The tester found an issue. I\'m asking the Fixer Agent to investigate."),\n        "mission_complete": (PresencePriority.IMPORTANT, "Mission complete. I recorded what worked."),\n        "repository_changed": (PresencePriority.NORMAL, "Your repository changed. I can re-index it in the background."),\n        "plugin_update": (PresencePriority.NORMAL, "A plugin update is available."),\n        "visual_pattern_learned": (PresencePriority.NORMAL, "I learned something new from the camera."),\n    }\n    def __init__(self, director: ConversationDirector | None = None) -> None: self.director = director or ConversationDirector()\n    def handle_event(self, event_type: str, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n        payload = payload or {}; priority, default_message = self.IMPORTANT_EVENTS.get(event_type, (PresencePriority.LOW, "I noticed an update."))\n        return self.director.request_speech(payload.get("message") or default_message, priority, payload.get("category", "mission"), reason=event_type)\n')
    write('buster/presence/context_awareness.py', 'from __future__ import annotations\nfrom typing import Dict, Any\n\nclass ContextAwareness:\n    def describe_context(self, active_window: str = "", device_hint: str = "", idle_minutes: int = 0) -> Dict[str, Any]:\n        window = (active_window or "").lower(); device = (device_hint or "").lower(); suggestions = []\n        if "android studio" in window: suggestions.append("I can monitor Logcat while you work in Android Studio.")\n        if "visual studio code" in window or "vscode" in window: suggestions.append("I can watch your project files and suggest a re-index when they change.")\n        if "esp32" in device or "cp210" in device or "ch340" in device: suggestions.append("ESP32-style device detected. Arduino and ESP32 plugins may help.")\n        if idle_minutes >= 20: suggestions.append(f"Your workspace has been idle for about {idle_minutes} minutes.")\n        return {"active_window": active_window, "device_hint": device_hint, "idle_minutes": idle_minutes, "suggestions": suggestions}\n')
    write('buster/presence/engine.py', 'from __future__ import annotations\nfrom typing import Dict, Any, Optional\nfrom .director import ConversationDirector\nfrom .ambient_awareness import AmbientAwareness\nfrom .context_awareness import ContextAwareness\nfrom .modes import state_for_activity\n\nclass PresenceEngine:\n    def __init__(self, data_dir: str = "data") -> None:\n        self.director = ConversationDirector(data_dir=data_dir); self.ambient = AmbientAwareness(self.director); self.context = ContextAwareness()\n    def set_companion_mode(self) -> Dict[str, Any]: return self.director.set_mode("companion")\n    def on_activity(self, activity: str, message: str | None = None) -> Dict[str, Any]:\n        emotion = state_for_activity(activity); speech = self.director.request_speech(message, category="mission", reason=activity) if message else None\n        return {"activity": activity, "emotion": emotion, "speech": speech}\n    def on_event(self, event_type: str, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]: return self.ambient.handle_event(event_type, payload)\n    def inspect_context(self, active_window: str = "", device_hint: str = "", idle_minutes: int = 0) -> Dict[str, Any]:\n        ctx = self.context.describe_context(active_window, device_hint, idle_minutes)\n        for suggestion in ctx.get("suggestions", [])[:1]: self.director.request_speech(suggestion, category="context", reason="context awareness")\n        return ctx\n')
    write('buster/visual_learning/__init__.py', 'from .observation import VisualObservation\nfrom .memory import VisualMemory\nfrom .learner import VisualLearner\nfrom .patterns import VisualPatternEngine\nfrom .engine import VisualLearningEngine\n__all__ = ["VisualObservation", "VisualMemory", "VisualLearner", "VisualPatternEngine", "VisualLearningEngine"]\n')
    write('buster/visual_learning/observation.py', 'from __future__ import annotations\nfrom dataclasses import dataclass, asdict\nfrom datetime import datetime, timezone\nfrom typing import Dict, Any\n\n@dataclass\nclass VisualObservation:\n    label: str\n    source: str = "camera"\n    confidence: float = 0.0\n    context: str = ""\n    details: Dict[str, Any] | None = None\n    timestamp: str = ""\n    def to_dict(self) -> Dict[str, Any]:\n        data = asdict(self)\n        if not data.get("timestamp"): data["timestamp"] = datetime.now(timezone.utc).isoformat(timespec="seconds")\n        if data.get("details") is None: data["details"] = {}\n        return data\n')
    write('buster/visual_learning/memory.py', 'from __future__ import annotations\nimport json\nfrom pathlib import Path\nfrom typing import Dict, Any\n\nclass VisualMemory:\n    def __init__(self, data_dir: str | Path = "data") -> None:\n        self.data_dir = Path(data_dir); self.data_dir.mkdir(parents=True, exist_ok=True); self.path = self.data_dir / "visual_learning_memory.json"\n        if not self.path.exists(): self.path.write_text(json.dumps({"observations": [], "patterns": [], "updated": None}, indent=2), encoding="utf-8")\n    def load(self) -> Dict[str, Any]:\n        try: return json.loads(self.path.read_text(encoding="utf-8"))\n        except Exception: return {"observations": [], "patterns": [], "updated": None}\n    def save(self, data: Dict[str, Any]) -> None: self.path.write_text(json.dumps(data, indent=2), encoding="utf-8")\n    def add_observation(self, observation: Dict[str, Any]) -> Dict[str, Any]:\n        data = self.load(); data.setdefault("observations", []).append(observation); data["observations"] = data["observations"][-1000:]; data["updated"] = observation.get("timestamp"); self.save(data); return observation\n    def add_pattern(self, pattern: Dict[str, Any]) -> Dict[str, Any]:\n        data = self.load(); data.setdefault("patterns", []).append(pattern); data["patterns"] = data["patterns"][-500:]; data["updated"] = pattern.get("updated"); self.save(data); return pattern\n')
    write('buster/visual_learning/patterns.py', 'from __future__ import annotations\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom typing import Dict, Any, List\n\nclass VisualPatternEngine:\n    def discover_patterns(self, observations: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n        labels = [o.get("label", "unknown") for o in observations]; contexts = [o.get("context", "") for o in observations if o.get("context")]; out = []\n        for label, count in Counter(labels).items():\n            if count >= 2: out.append({"type": "repeated_visual_label", "label": label, "count": count, "confidence": min(0.99, 0.50 + count * 0.10), "updated": datetime.now(timezone.utc).isoformat(timespec="seconds"), "recommendation": f"Remember visual pattern: {label}"})\n        for context, count in Counter(contexts).items():\n            if count >= 2: out.append({"type": "repeated_visual_context", "context": context, "count": count, "confidence": min(0.99, 0.50 + count * 0.10), "updated": datetime.now(timezone.utc).isoformat(timespec="seconds"), "recommendation": f"This visual context appears often: {context}"})\n        return out\n')
    write('buster/visual_learning/learner.py', 'from __future__ import annotations\nfrom typing import Dict, Any, List\nfrom .observation import VisualObservation\nfrom .memory import VisualMemory\nfrom .patterns import VisualPatternEngine\n\nclass VisualLearner:\n    def __init__(self, data_dir: str = "data") -> None: self.memory = VisualMemory(data_dir); self.patterns = VisualPatternEngine()\n    def observe(self, label: str, confidence: float = 0.0, context: str = "", source: str = "camera", details: Dict[str, Any] | None = None) -> Dict[str, Any]:\n        obs = VisualObservation(label=label, confidence=confidence, context=context, source=source, details=details or {}).to_dict(); self.memory.add_observation(obs); return obs\n    def learn_patterns(self) -> List[Dict[str, Any]]:\n        data = self.memory.load(); patterns = self.patterns.discover_patterns(data.get("observations", []))\n        for p in patterns: self.memory.add_pattern(p)\n        return patterns\n    def summarize(self) -> Dict[str, Any]:\n        data = self.memory.load(); return {"observations": len(data.get("observations", [])), "patterns": len(data.get("patterns", [])), "updated": data.get("updated")}\n')
    write('buster/visual_learning/engine.py', 'from __future__ import annotations\nfrom typing import Dict, Any\nfrom .learner import VisualLearner\n\nclass VisualLearningEngine:\n    def __init__(self, data_dir: str = "data") -> None: self.learner = VisualLearner(data_dir)\n    def record_camera_observation(self, label: str, confidence: float = 0.0, context: str = "", details: Dict[str, Any] | None = None) -> Dict[str, Any]: return self.learner.observe(label=label, confidence=confidence, context=context, source="camera", details=details or {})\n    def learn_from_recent_camera(self) -> Dict[str, Any]:\n        patterns = self.learner.learn_patterns(); return {"patterns_found": len(patterns), "patterns": patterns, "summary": self.learner.summarize()}\n')
    write('buster/vision/learning_bridge.py', 'from __future__ import annotations\nfrom typing import Dict, Any\ntry:\n    from buster.visual_learning import VisualLearningEngine\nexcept Exception:\n    VisualLearningEngine = None\n\nclass VisionLearningBridge:\n    def __init__(self, data_dir: str = "data") -> None: self.engine = VisualLearningEngine(data_dir) if VisualLearningEngine else None\n    def record_detection(self, label: str, confidence: float = 0.0, context: str = "", details: Dict[str, Any] | None = None) -> Dict[str, Any]:\n        if not self.engine: return {"ok": False, "reason": "VisualLearningEngine unavailable"}\n        return {"ok": True, "observation": self.engine.record_camera_observation(label, confidence, context, details or {})}\n    def learn(self) -> Dict[str, Any]:\n        if not self.engine: return {"ok": False, "reason": "VisualLearningEngine unavailable"}\n        result = self.engine.learn_from_recent_camera(); result["ok"] = True; return result\n')
    write('buster/workspace/presence_dashboard.py', 'from __future__ import annotations\nfrom typing import Dict, Any\ntry:\n    from buster.visual_learning import VisualLearningEngine\nexcept Exception:\n    VisualLearningEngine = None\n\nclass PresenceDashboard:\n    def __init__(self, data_dir: str = "data") -> None: self.visual = VisualLearningEngine(data_dir) if VisualLearningEngine else None\n    def snapshot(self) -> Dict[str, Any]:\n        visual_summary = self.visual.learner.summarize() if self.visual else {}\n        return {"title": "Buster Presence", "mode": "companion", "status": "alive", "visual_learning": visual_summary, "capabilities": ["talk_first", "ambient_awareness", "context_awareness", "camera_learning"]}\n')
    write('buster/ui/widgets/presence_widget.py', 'from __future__ import annotations\nfrom typing import Dict, Any\nclass PresenceWidgetModel:\n    def __init__(self) -> None: self.mode = "companion"; self.emotion = "relaxed"; self.last_message = "Buster is present."\n    def update(self, mode: str | None = None, emotion: str | None = None, message: str | None = None) -> Dict[str, Any]:\n        if mode: self.mode = mode\n        if emotion: self.emotion = emotion\n        if message: self.last_message = message\n        return self.to_dict()\n    def to_dict(self) -> Dict[str, Any]: return {"mode": self.mode, "emotion": self.emotion, "last_message": self.last_message}\n')
    write('buster/brain/planner/presence_planner_bridge.py', 'from __future__ import annotations\nfrom typing import Dict, Any\ntry:\n    from buster.presence import PresenceEngine\nexcept Exception:\n    PresenceEngine = None\nclass PresencePlannerBridge:\n    def __init__(self, data_dir: str = "data") -> None: self.engine = PresenceEngine(data_dir) if PresenceEngine else None\n    def announce_plan(self, plan_name: str, confidence: float = 0.0, risk: str = "low") -> Dict[str, Any]:\n        message = f"I created the plan: {plan_name}. Confidence {round(confidence * 100)} percent. Risk {risk}."\n        if not self.engine: return {"ok": False, "message": message}\n        return {"ok": True, "speech": self.engine.director.request_speech(message, category="mission", reason="planner announcement")}\n')

    create_json("data/presence_settings.json", {"enabled": True, "mode": "companion", "quiet_mode": False, "cooldown_seconds": 20, "max_items_per_hour": 24, "min_priority": "normal", "allow_greetings": True, "allow_idle_checkins": True, "allow_camera_learning_comments": True, "allow_engineering_suggestions": True})
    create_json("data/presence_state.json", {"mode": "companion", "emotion": "relaxed", "updated": utc_now()})
    create_json("data/presence_speech_queue.json", [])
    create_json("data/visual_learning_memory.json", {"observations": [], "patterns": [], "updated": None})
    create_json("data/camera_learning_state.json", {"enabled": True, "learn_like_human": True, "updated": utc_now()})
    print("\nSUCCESS: Buster v4.5 Presence + Visual Learning installed.")
    print("Next: python test_v4_5_presence_visual_learning.py")
if __name__ == "__main__": main()
